#!/usr/bin/env python3
"""zip-password-finder - Find the password of protected ZIP files"""

import argparse
import itertools
import os
import sys
import time
import zipfile
from typing import List, Optional, Set

# Character sets
CHARSETS = {
    'l': 'abcdefghijklmnopqrstuvwxyz',
    'u': 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
    'd': '0123456789',
    'h': '0123456789abcdef',
    'H': '0123456789ABCDEF',
    's': ' \"space\" and symbols',
}

def load_charset_from_file(filepath: str) -> str:
    """Load charset from a file, one character per line."""
    with open(filepath, 'r') as f:
        return ''.join(line.strip() for line in f if line.strip())

def is_zip_encrypted(zip_path: str, file_number: int) -> bool:
    """Check if a specific file in the zip is encrypted."""
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            if file_number < 0 or file_number >= len(zf.namelist()):
                return False
            return zf.getinfo(zf.namelist()[file_number]).encrypt_flag
    except Exception:
        return False

def test_password(zip_path: str, password: bytes, file_number: int) -> bool:
    """Test if a password works for the specified file in the zip."""
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            info = zf.getinfo(zf.namelist()[file_number])
            if info.compress_type == zipfile.ZIP_DEFLATED:
                # AES encryption
                try:
                    zf.extract(info, path=None, pwd=password)
                    return True
                except:
                    return False
            else:
                # ZipCrypto
                try:
                    zf.extract(info, path=None, pwd=password)
                    return True
                except:
                    return False
    except Exception:
        return False

def find_password_dictionary(zip_path: str, dictionary_path: str, file_number: int) -> Optional[str]:
    """Find password using a dictionary file."""
    try:
        with open(dictionary_path, 'r') as f:
            passwords = [line.strip() for line in f if line.strip()]
    except Exception:
        return None

    for password in passwords:
        if test_password(zip_path, password.encode(), file_number):
            return password
    return None

def generate_passwords(charset: str, min_len: int, max_len: int, starting_password: Optional[str] = None) -> List[str]:
    """Generate passwords based on charset and length range."""
    chars = list(charset)
    passwords = []

    if starting_password:
        # Start from the given password
        start_len = len(starting_password)
        if start_len < min_len:
            start_len = min_len
        if start_len > max_len:
            return []

        # Generate passwords starting from the given one
        for length in range(start_len, max_len + 1):
            for combo in itertools.product(chars, repeat=length):
                password = ''.join(combo)
                if password >= starting_password:
                    passwords.append(password)
    else:
        # Generate all passwords in the range
        for length in range(min_len, max_len + 1):
            for combo in itertools.product(chars, repeat=length):
                passwords.append(''.join(combo))

    return passwords

def find_password_bruteforce(zip_path: str, charset: str, min_len: int, max_len: int, 
                            starting_password: Optional[str] = None, file_number: int = 0) -> Optional[str]:
    """Find password using brute force."""
    passwords = generate_passwords(charset, min_len, max_len, starting_password)

    for password in passwords:
        if test_password(zip_path, password.encode(), file_number):
            return password
    return None

def main():
    parser = argparse.ArgumentParser(
        description='Find the password of protected ZIP files',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog='''
Examples:
  zip-password-finder --inputFile secret.zip --passwordDictionary words.txt
  zip-password-finder --inputFile secret.zip --charset l --minPasswordLen 1 --maxPasswordLen 6
'''
    )

    parser.add_argument('-i', '--inputFile', required=True,
                        help='path to zip input file')
    parser.add_argument('-w', '--workers', type=int, default=1,
                        help='number of workers')
    parser.add_argument('-p', '--passwordDictionary',
                        help='path to a password dictionary file')
    parser.add_argument('-c', '--charset', default='lud',
                        help='charset to use to generate password')
    parser.add_argument('--charsetFile',
                        help='path to a charset file')
    parser.add_argument('--minPasswordLen', type=int, default=1,
                        help='minimum password length')
    parser.add_argument('--maxPasswordLen', type=int, default=10,
                        help='maximum password length')
    parser.add_argument('--fileNumber', type=int, default=0,
                        help='file number in the zip archive')
    parser.add_argument('-s', '--startingPassword',
                        help='password to start from')
    parser.add_argument('-h', '--help', action='store_true',
                        help='Print help')
    parser.add_argument('-V', '--version', action='store_true',
                        help='Print version')

    args = parser.parse_args()

    if args.help:
        parser.print_help()
        return 0

    if args.version:
        print('zip-password-finder 0.10.3')
        return 0

    # Validate inputs
    if not os.path.exists(args.inputFile):
        print(f'CLI argument error - \"{args.inputFile}\" does not exist')
        return 1

    if args.workers < 1:
        print(f'CLI argument error - \"{args.workers}\" must be positive')
        return 1

    # Determine charset
    if args.charsetFile:
        if not os.path.exists(args.charsetFile):
            print(f'CLI argument error - \"{args.charsetFile}\" does not exist')
            return 1
        charset = load_charset_from_file(args.charsetFile)
    else:
        charset = args.charset

    # Validate charset
    if args.charsetFile:
        if not charset:
            print(f'CLI argument error - \"{args.charsetFile}\" is empty')
            return 1
    else:
        if charset not in CHARSETS:
            print(f'CLI argument error - \"{charset}\" is not a valid charset')
            return 1

    # Validate starting password
    starting_password = None
    if args.startingPassword:
        if len(args.startingPassword) < args.minPasswordLen or len(args.startingPassword) > args.maxPasswordLen:
            print(f'CLI argument error - \"{args.startingPassword}\" does not respect \'max_password_len\' or \'min_password_len\' configuration')
            return 1
        starting_password = args.startingPassword

    # Check if file is encrypted
    try:
        with zipfile.ZipFile(args.inputFile, 'r') as zf:
            if args.fileNumber < 0 or args.fileNumber >= len(zf.namelist()):
                print(f'Invalid zip file error - the selected file in the archive is not encrypted (file_number:{args.fileNumber} file_name:{zf.namelist()[args.fileNumber]})')
                return 1
            if not zf.getinfo(zf.namelist()[args.fileNumber]).encrypt_flag:
                print(f'Invalid zip file error - the selected file in the archive is not encrypted (file_number:{args.fileNumber} file_name:{zf.namelist()[args.fileNumber]})')
                return 1
    except Exception as e:
        print(f'Invalid zip file error - {e}')
        return 1

    # Find password
    start_time = time.perf_counter()

    if args.passwordDictionary:
        if not os.path.exists(args.passwordDictionary):
            print(f'CLI argument error - \"{args.passwordDictionary}\" does not exist')
            return 1
        password = find_password_dictionary(args.inputFile, args.passwordDictionary, args.fileNumber)
    else:
        password = find_password_bruteforce(args.inputFile, charset, args.minPasswordLen, args.maxPasswordLen, 
                                           starting_password, args.fileNumber)

    elapsed = time.perf_counter() - start_time

    if password:
        print(f'Time elapsed: {elapsed:.6f}s')
        print(f'Password found:{password}')
        return 0
    else:
        print(f'Time elapsed: {elapsed:.6f}s')
        print('Password not found')
        return 0

if __name__ == '__main__':
    sys.exit(main())
EOF"}

