use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader, Read};
use std::path::Path;
use std::time::Instant;

#[derive(Debug)]
struct Args {
    input_file: Option<String>,
    workers: Option<usize>,
    password_dictionary: Option<String>,
    charset: String,
    charset_file: Option<String>,
    min_password_len: usize,
    max_password_len: usize,
    file_number: usize,
    starting_password: Option<String>,
    help: bool,
}

fn parse_args() -> Args {
    let args: Vec<String> = env::args().collect();

    let mut input_file: Option<String> = None;
    let mut workers: Option<usize> = None;
    let mut password_dictionary: Option<String> = None;
    let mut charset = String::from("lud");
    let mut charset_file: Option<String> = None;
    let mut min_password_len: usize = 1;
    let mut max_password_len: usize = 10;
    let mut file_number: usize = 0;
    let mut starting_password: Option<String> = None;
    let mut help = false;

