            if i + 1 < args.len() {
                input_file = Some(args[i + 1].clone());
                i += 2;
            } else {
                eprintln!("error: the following required arguments were not provided:\n  --inputFile <inputFile>");
                std::process::exit(2);
            }
        } else if arg == "--workers" || arg == "-w" {
            if i + 1 < args.len() {
                workers = Some(args[i + 1].parse().unwrap_or(1));
                i += 2;
            } else {
                eprintln!("error: the following required arguments were not provided:\n  --workers <workers>");
                std::process::exit(2);
            }
        } else if arg == "--passwordDictionary" || arg == "-p" {
            if i + 1 < args.len() {
                password_dictionary = Some(args[i + 1].clone());
