            if i + 1 < args.len() {
                charset = args[i + 1].clone();
                i += 2;
            } else {
                eprintln!("error: the following required arguments were not provided:\n  --charset <charset>");
                std::process::exit(2);
            }
        } else if arg == "--charsetFile" {
            if i + 1 < args.len() {
                charset_file = Some(args[i + 1].clone());
                i += 2;
            } else {
                eprintln!("error: the following required arguments were not provided:\n  --charsetFile <charsetFile>");
                std::process::exit(2);
            }
        } else if arg == "--minPasswordLen" {
            if i + 1 < args.len() {
                min_password_len = args[i + 1].parse().unwrap_or(1);
                i += 2;
            } else {
                eprintln!("error: the following required arguments were not provided:\n  --minPasswordLen <minPasswordLen>");
                std::process::exit(2);
