        }
    }

    if help {
        print_help();
        std::process::exit(0);
    }

    if input_file.is_none() {
        eprintln!("error: the following required arguments were not provided:\n  --inputFile <inputFile>");
        std::process::exit(2);
    }

    if password_dictionary.is_none() && charset_file.is_none() {
        eprintln!("CLI argument error - \"'passwordDictionary' does not exist\"");
        std::process::exit(1);
    }

    Args {
        input_file,
        workers,
        password_dictionary,
        charset,
        charset_file,
        min_password_len,
        max_password_len,
