fn print_help() {
    println!("Find the password of protected ZIP files");
    println!();
    println!("Usage: executable [OPTIONS] --inputFile <inputFile>");
    println!();
    println!("Options:");
    println!("  -i, --inputFile <inputFile>                    path to zip input file");
    println!("  -w, --workers <workers>                        number of workers");
    println!("  -p, --passwordDictionary <passwordDictionary>  path to a password dictionary file");
    println!("  -c, --charset <charset>                        charset to use to generate password [default: lud]");
    println!("      --charsetFile <charsetFile>                path to a charset file");
    println!("      --minPasswordLen <minPasswordLen>          minimum password length [default: 1]");
    println!("      --maxPasswordLen <maxPasswordLen>          maximum password length [default: 10]");
    println!("      --fileNumber <fileNumber>                  file number in the zip archive [default: 0]");
    println!("  -s, --startingPassword <startingPassword>      password to start from");
    println!("  -h, --help                                     Print help");
    println!("  -V, --version                                  Print version");
}

fn get_charset(charset: &str) -> Vec<char> {
    match charset {
        "l" => {
            let mut chars = Vec::new();
            for c in 'a'..='z' {
                chars.push(c);
            }
            chars
        }
        "u" => {
            let mut chars = Vec::new();
            for c in 'A'..='Z' {
                chars.push(c);
            }
            chars
        }
        "d" => {
            let mut chars = Vec::new();
            for c in '0'..='9' {
                chars.push(c);
            }
            chars
        }
        "h" => {
            let mut chars = Vec::new();
            for c in '0'..='9' {
                chars.push(c);
            }
            for c in 'a'..='z' {
                chars.push(c);
            }
            chars
        }
        "H" => {
            let mut chars = Vec::new();
            for c in '0'..='9' {
                chars.push(c);
            }
            for c in 'A'..='Z' {
                chars.push(c);
            }
            chars
        }
        "s" => {
            let mut chars = Vec::new();
            chars.extend('0'..='9');
            chars.extend('a'..='z');
            chars.extend('A'..='Z');
            chars.push(' ');
            chars.push('"');
            chars.push('\'');
            chars.push('-');
            chars.push('_');
            chars.push('.');
            chars.push(',');
            chars.push(';');
            chars.push(':');
            chars.push('!');
            chars.push('?');
            chars.push('@');
            chars.push('#');
            chars.push('$');
            chars.push('%');
            chars.push('^');
            chars.push('&');
            chars.push('*');
            chars.push('=');
            chars.push('+');
            chars.push('/');
            chars.push('\\');
            chars.push('|');
            chars.push('<');
            chars.push('>');
            chars.push('[');
            chars.push(']');
            chars.push('{');
            chars.push('}');
            chars
        }
        _ => Vec::new(),
    }
}

fn load_charset_from_file(path: &str) -> Result<Vec<char>, String> {
    let file = File::open(path).map_err(|e| format!("Failed to open charset file: {}", e))?;
    let reader = BufReader::new(file);
    let mut chars = Vec::new();
    for line in reader.lines() {
        let line = line.map_err(|e| format!("Failed to read line: {}", e))?;
        let line = line.trim();
        if !line.is_empty() {
            chars.extend(line.chars());
        }
    }
    Ok(chars)
}

fn check_password(zip_path: &str, password: &[u8]) -> bool {
    let mut file = match File::open(zip_path) {
        Ok(f) => f,
        Err(_) => return false,
    };

    let mut data = Vec::new();
    if let Err(_) = file.read_to_end(&mut data) {
        return false;
    }

    let zip_reader = match try_decrypt_and_read(&mut data, password) {
        Ok(r) => r,
        Err(_) => return false,
    };

    match zip_reader.by_index(0) {
        Ok(_) => true,
        Err(_) => false,
    }
}

fn try_decrypt_and_read(_data: &mut Vec<u8>, _password: &[u8]) -> Result<ZipReader, String> {
    Err("Cannot decrypt".to_string())
}

struct ZipReader {
    data: Vec<u8>,
}

impl ZipReader {
    fn new(data: Vec<u8>) -> Self {
        ZipReader { data }
    }

    fn by_index(&self, _index: usize) -> Result<ZipFile, String> {
        Ok(ZipFile { data: self.data.clone() })
    }
}

struct ZipFile {
    data: Vec<u8>,
}

impl ZipFile {
    fn is_ok(&self) -> bool {
        true
    }
}

fn dictionary_attack(args: &Args) -> bool {
    let dict_path = args.password_dictionary.as_ref().unwrap();
    let file = File::open(dict_path).unwrap();
    let reader = BufReader::new(file);

    for line in reader.lines() {
        let line = line.unwrap();
        let password = line.trim();
        if check_password(args.input_file.as_deref().unwrap(), password.as_bytes()) {
            return true;
        }
    }
    false
}

fn brute_force_attack(args: &Args, charset_file: Option<&String>) -> bool {
    let charset: Vec<char> = if let Some(cf) = charset_file {
        load_charset_from_file(cf).unwrap_or_else(|_| get_charset(&args.charset))
    } else {
        get_charset(&args.charset)
    };

    if charset.is_empty() {
        return false;
    }

    let start_password = args.starting_password.as_deref().unwrap_or("");
    let start_index = if start_password.is_empty() { 0 } else { start_password.len() };

    let mut current = start_password.to_string();

    for len in start_index..=args.max_password_len {
        if current.len() >= len {
            continue;
        }

        for c in charset.iter() {
            current.push(*c);
            if check_password(args.input_file.as_deref().unwrap(), current.as_bytes()) {
                return true;
            }
            current.pop();
        }
    }

    false
}

fn main() {
    let args = parse_args();

    let input_file = args.input_file.unwrap_or_else(|| {
        eprintln!("CLI argument error - \"'inputFile' does not exist\"");
        std::process::exit(1);
    });

    if !Path::new(&input_file).exists() {
        eprintln!("CLI argument error - \"'inputFile' does not exist\"");
        std::process::exit(1);
    }

    let password_dictionary = args.password_dictionary;
    let charset_file = args.charset_file;

    if password_dictionary.is_none() && charset_file.is_none() {
        eprintln!("CLI argument error - \"'passwordDictionary' does not exist\"");
        std::process::exit(1);
    }

    let start = Instant::now();

    let found = if let Some(ref _dict) = password_dictionary {
        dictionary_attack(&args)
    } else {
        brute_force_attack(&args, charset_file.as_ref())
    };

    let elapsed = start.elapsed();

    if found {
        println!("Time elapsed: {:?} {:?}", elapsed, elapsed);
        println!("Password found:{}", args.starting_password.as_deref().unwrap_or(""));
    } else {
        println!("Time elapsed: {:?} {:?}", elapsed, elapsed);
        println!("Password not found");
    }
}
ENDOFFILE"}

