{"command": "cat > src/main.rs << 'RUSTEOF'
use clap::Parser;
use std::collections::HashSet;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;
use std::process;
use std::thread;
use std::time::Instant;
use zip::ZipArchive;

#[derive(Parser, Debug)]
#[command(name = "executable")]
#[command(author = "zip-password-finder")]
#[command(version = "0.10.3")]
#[command(about = "Find the password of protected ZIP files", long_about = None)]
struct Args {
    /// path to zip input file
    #[arg(short = 'i', long = "inputFile")]
    input_file: Option<String>,

    /// number of workers
    #[arg(short = 'w', long = "workers", default_value = "1")]
    workers: usize,

    /// path to a password dictionary file
    #[arg(short = 'p', long = "passwordDictionary")]
    password_dictionary: Option<String>,

    /// charset to use to generate password
    #[arg(short = 'c', long = "charset", default_value = "lud")]
    charset: String,

    /// path to a charset file
    #[arg(long = "charsetFile")]
    charset_file: Option<String>,

    /// minimum password length
    #[arg(long = "minPasswordLen", default_value = "1")]
    min_password_len: usize,

    /// maximum password length
    #[arg(long = "maxPasswordLen", default_value = "10")]
    max_password_len: usize,

    /// file number in the zip archive
    #[arg(long = "fileNumber", default_value = "0")]
    file_number: usize,

    /// password to start from
    #[arg(short = 's', long = "startingPassword")]
    starting_password: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CharsetType {
    Lowercase,
    Uppercase,
    Digits,
    HexLower,
    HexUpper,
    SpaceSymbols,
}

impl CharsetType {
    fn from_char(c: char) -> Option<Self> {
        match c {
            'l' => Some(CharsetType::Lowercase),
            'u' => Some(CharsetType::Uppercase),
            'd' => Some(CharsetType::Digits),
            'h' => Some(CharsetType::HexLower),
            'H' => Some(CharsetType::HexUpper),
            's' => Some(CharsetType::SpaceSymbols),
            _ => None,
        }
    }

    fn chars(&self) -> Vec<char> {
        match self {
            CharsetType::Lowercase => "abcdefghijklmnopqrstuvwxyz".chars().collect(),
            CharsetType::Uppercase => "ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect(),
            CharsetType::Digits => "0123456789".chars().collect(),
            CharsetType::HexLower => "0123456789abcdef".chars().collect(),
            CharsetType::HexUpper => "0123456789ABCDEF".chars().collect(),
            CharsetType::SpaceSymbols => {
                let mut chars = " \t\n\r!@#$%^&*()_+-=[]{}|;':\",./<>?".chars().collect();
                chars.sort();
                chars
            }
        }
    }
}

fn parse_charset_file(path: &str) -> Result<Vec<CharsetType>, String> {
    let file = File::open(path).map_err(|e| format!("Failed to open charset file: {}", e))?;
    let reader = BufReader::new(file);
    let mut charsets = HashSet::new();

    for line in reader.lines() {
        let line = line.map_err(|e| format!("Failed to read line: {}", e))?;
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        for c in line.chars() {
            if let Some(charset) = CharsetType::from_char(c) {
                charsets.insert(charset);
            }
        }
    }

    if charsets.is_empty() {
        return Err("Charset file is empty or contains no valid characters".to_string());
    }

    Ok(charsets.into_iter().collect())
}

fn generate_passwords(
    charset: &[char],
    min_len: usize,
    max_len: usize,
    starting_password: Option<&str>,
) -> Vec<String> {
    let mut passwords = Vec::new();

    if let Some(starting) = starting_password {
        passwords.push(starting.to_string());
    }

    for len in min_len..=max_len {
        if len == 0 {
            continue;
        }

        let mut chars: Vec<char> = charset.to_vec();
        chars.sort();

        // Generate all combinations of this length
        generate_combinations_recursive(&mut passwords, &chars, len, 0, Vec::new());
    }

    // Remove duplicates while preserving order
    let mut seen = HashSet::new();
    passwords.retain(|p| seen.insert(p.clone()));

    passwords
}

fn generate_combinations_recursive(
    passwords: &mut Vec<String>,
    charset: &[char],
    length: usize,
    depth: usize,
    current: Vec<char>,
) {
    if depth == length {
        passwords.push(current.into_iter().collect());
        return;
    }

    for c in charset {
        current.push(*c);
        generate_combinations_recursive(passwords, charset, length, depth + 1, current.clone());
        current.pop();
    }
}

fn test_password(zip_path: &str, password: &str, file_number: usize) -> bool {
    let file = File::open(zip_path).unwrap_or_else(|_| {
        panic!("Failed to open zip file: {}", zip_path);
    });

    let mut archive = ZipArchive::new(file).unwrap_or_else(|_| {
        panic!("Failed to open zip archive: {}", zip_path);
    });

    if file_number >= archive.len() {
        return false;
    }

    let file_info = archive.by_index(file_number).unwrap_or_else(|_| {
        panic!("Failed to get file at index {}: {}", file_number, zip_path);
    });

    let mut decrypted_data = Vec::new();
    if let Err(_) = archive.extract_to_password(file_number, &mut decrypted_data, password.as_bytes()) {
        return false;
    }

    true
}

fn main() {
    let args = Args::parse();

    let input_file = match &args.input_file {
        Some(f) => f.clone(),
        None => {
            eprintln!("error: the following required arguments were not provided:");
            eprintln!("  --inputFile <inputFile>");
            eprintln!();
            eprintln!("Usage: executable --inputFile <inputFile>");
            eprintln!();
            eprintln!("For more information, try '--help'");
            process::exit(2);
        }
    };

    if !Path::new(&input_file).exists() {
        eprintln!("CLI argument error - \"'inputFile' does not exist\"");
        process::exit(1);
    }

    let charset: Vec<CharsetType> = if let Some(ref charset_file) = args.charset_file {
        match parse_charset_file(charset_file) {
            Ok(cs) => cs,
            Err(e) => {
                eprintln!("CLI argument error - {}", e);
                process::exit(1);
            }
        }
    } else {
        args.charset
            .chars()
            .filter_map(CharsetType::from_char)
            .collect()
    };

    if charset.is_empty() {
        eprintln!("CLI argument error - \"'charset' must not be empty\"");
        process::exit(1);
    }

    if args.workers == 0 {
        eprintln!("CLI argument error - \"'workers' must be positive\"");
        process::exit(1);
    }

    if args.max_password_len < args.min_password_len {
        eprintln!("CLI argument error - \"'maxPasswordLen' must be equal or greater than 'minPasswordLen'\"");
        process::exit(1);
    }

    let starting_password = args.starting_password.as_deref();

    let passwords = generate_passwords(&charset.chars().collect::<Vec<_>>(), args.min_password_len, args.max_password_len, starting_password);

    let start_time = Instant::now();

    let results = if args.workers == 1 {
        for password in &passwords {
            if test_password(&input_file, password, args.file_number) {
                println!("Time elapsed: {:?}", start_time.elapsed());
                println!("Password found:{}", password);
                process::exit(0);
            }
        }
        println!("Time elapsed: {:?}", start_time.elapsed());
        println!("Password not found");
        process::exit(1);
    } else {
        let mut handles = Vec::new();
        let results = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));

        for password in &passwords {
            let input_file = input_file.clone();
            let file_number = args.file_number;
            let results = results.clone();

            let handle = thread::spawn(move || {
                if test_password(&input_file, password, file_number) {
                    let mut res = results.lock().unwrap();
                    res.push((password.clone(), true));
                }
            });

            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        let found = results.lock().unwrap();
        if !found.is_empty() {
            let (password, _) = found[0].clone();
            println!("Time elapsed: {:?}", start_time.elapsed());
            println!("Password found:{}", password);
            process::exit(0);
        }

        println!("Time elapsed: {:?}", start_time.elapsed());
        println!("Password not found");
        process::exit(1);
    };
}
RUSTEOF"}

